    #[test]
    fn sidecar_segment_decodes_canonical_struct_via_real_python() {
        // Stub child validates the REQUEST contract (op == segment, params
        // carry the required video_path) then prints a FIXED matte payload —
        // no segmentation model required. The request-side assert keeps the
        // adapter and the reference sidecar from silently drifting apart (the
        // reference sidecar hard-fails without params.video_path).
        let dir = tempfile::tempdir().unwrap();
        let script = dir.path().join("segment.py");
        let mut f = std::fs::File::create(&script).unwrap();
        f.write_all(
            br#"import sys, json
req = json.loads(sys.stdin.readline())
assert req["op"] == "segment", req["op"]
assert req["params"]["video_path"] == "assets/aa/sha.mp4", req["params"]
print(json.dumps({"op": "segment", "result": {
    "matte_asset_hash": "aa11bb22cc33dd44ee55ff660011223344556677889900112233445566778899",
    "width": 1920,
    "height": 1080,
    "frames": [{"t_tk": 0}, {"t_tk": 8000}]
}}))
"#,
        )
        .unwrap();

        let key = cache_key("segment");
        let backend = Backend::Sidecar {
            program: "/usr/bin/python3".to_string(),
            args: vec![script.to_str().unwrap().to_string()],
        };
        let data =
            run_segment(&key, &backend, "an-1", "assets/aa/sha.mp4").expect("segment round-trip");
        assert_eq!(data.matte_asset_hash.as_str().len(), 64);
        assert_eq!(data.width, 1920);
        assert_eq!(data.height, 1080);
        assert_eq!(data.frames.len(), 2);
        assert_eq!(data.frames[0].t_tk, Tick::new(0));
        assert_eq!(data.frames[1].t_tk, Tick::new(8000));
    }

