    /// Stub child that asserts the `gen_image` REQUEST contract (op,
    /// prompt, echoed seed, dims) and prints a FIXED image handle. The
    /// request-side asserts keep the adapter and the reference sidecar from
    /// drifting apart (the reference sidecar requires `prompt` + `seed`).
    /// No real diffusion model is required.
    fn write_gen_image_stub(dir: &std::path::Path) -> std::path::PathBuf {
        let script = dir.join("gen_image.py");
        let mut f = std::fs::File::create(&script).unwrap();
        f.write_all(
            br#"import sys, json
req = json.loads(sys.stdin.readline())
assert req["op"] == "gen_image", req["op"]
assert req["params"]["prompt"] == "a misty forest at dawn", req["params"]
seed = req["params"]["seed"]
print(json.dumps({"op": "gen_image", "result": {
    "image_path": "/tmp/vr-gen/%d.png" % seed,
    "width": req["params"]["width"],
    "height": req["params"]["height"],
    "seed": seed
}}))
"#,
        )
        .unwrap();
        script
    }

    #[test]
    fn sidecar_gen_image_decodes_canonical_struct_via_real_python() {
        let dir = tempfile::tempdir().unwrap();
        let script = write_gen_image_stub(dir.path());

        let key = cache_key("gen_image");
        let backend = Backend::Sidecar {
            program: "/usr/bin/python3".to_string(),
            args: vec![script.to_str().unwrap().to_string()],
        };
        let data = run_gen_image(&key, &backend, "a misty forest at dawn", 42, 1024, 768)
            .expect("gen_image round-trip");
        assert_eq!(data.image_path, "/tmp/vr-gen/42.png");
        assert_eq!(data.width, 1024);
        assert_eq!(data.height, 768);
        assert_eq!(data.seed, 42);
    }

    #[test]
    fn gen_image_same_seed_yields_identical_result() {
        // Determinism: same prompt + seed + dims → identical decoded result
        // (the seed is the reproducibility knob; the stub echoes it into the
        // handle so a seed mismatch would diverge the path).
        let dir = tempfile::tempdir().unwrap();
        let script = write_gen_image_stub(dir.path());
        let key = cache_key("gen_image");
        let backend = Backend::Sidecar {
            program: "/usr/bin/python3".to_string(),
            args: vec![script.to_str().unwrap().to_string()],
        };
        let first = run_gen_image(&key, &backend, "a misty forest at dawn", 7, 512, 512).unwrap();
        let second = run_gen_image(&key, &backend, "a misty forest at dawn", 7, 512, 512).unwrap();
        assert_eq!(first, second);
        assert_eq!(first.seed, 7);
    }

